            "purpose": "Implements the board port by calling the labels capability's trusted server read API."
          },
          {
            "path": "src/features/board/server/load-board.ts",
            "purpose": "Server-only DAL/read entrypoint; derives and verifies the current actor, composes adapters and the use-case, and returns DTOs."
          },
          {
            "path": "src/app/board/page.tsx",
            "purpose": "Thin RSC route entrypoint that calls the server-only board reader and renders the board view."
          },
          {
            "path": "src/features/board/ui/board-view.tsx",
            "purpose": "Pure board rendering from serialized board props; no persistence or authorization logic."
          },
          {
            "path": "src/features/board/__tests__/load-board.test.ts",
            "purpose": "Use-case tests with fake ports covering policy and failure outcomes."
          },
          {
            "path": "src/features/board/adapters/outbound/__tests__/readers.test.ts",
            "purpose": "Contract/adapter tests proving correct calls to the independent capability APIs and error mapping."
          },
          {
            "path": "src/features/board/ui/__tests__/board-view.test.tsx",
            "purpose": "Rendering tests for status groups, hidden archived items, and attached visible labels."
          },
          {
            "path": "e2e/board.spec.ts",
            "purpose": "Authenticated end-to-end coverage for authorized, unauthorized, archived, and dependency-failure scenarios."
          }
        ],
        "flows": [
          "GET /board -> src/app/board/page.tsx -> src/features/board/server/load-board.ts -> verify current session/actor -> compose work-items and labels readers -> src/features/board/use-cases/load-board.ts -> capability server APIs -> independent persistence owners -> board view model -> BoardView.",
          "Board use-case requests work items and labels with the same server-derived actor context; it removes archived work items, groups remaining items by status, attaches only labels returned as viewable, and treats a label explicitly requested but not viewable as an authorization failure.",
          "Work-items and labels never import one another or the board feature. Board outbound adapters depend only on their public trusted server-read contracts; persistence adapters remain private to each capability.",
          "Unexpected dependency failures are logged/captured once at the server boundary with request and board context, then mapped to a safe generic error. Expected authentication/authorization failures become a not-found or forbidden result according to product policy; no raw database/provider errors reach the RSC or client.",
          "Board is an RSC-owned read: pass serializable props directly to the UI, with no TanStack Query or self-HTTP Route Handler. If later exposed to external clients, add a separate GET Route Handler that calls the same use-case."
        ],
        "decisions": [
          {
            "topic": "Orchestration ownership",
            "choice": "Board feature use-case",
            "rationale": "Archived filtering, grouping, label attachment, and cross-capability authorization are board policy, not work-item or label persistence concerns."
          },
          {
            "topic": "Dependency direction",
            "choice": "Use-case ports with composition in the server-only DAL",
            "rationale": "The use-case remains framework- and adapter-independent while the DAL/inbound composition root selects trusted capability implementations."
          },
          {
            "topic": "Public surfaces",
            "choice": "Actor-scoped server read contracts for work items and labels",
            "rationale": "Capabilities remain independently changeable and expose DTOs/contracts rather than database rows or concrete repositories."
          },
          {
            "topic": "Authorization",
            "choice": "Recheck auth in the server-only DAL and capability read APIs",
            "rationale": "Proxy protection is insufficient; every data boundary must derive the actor server-side and enforce view permissions."
          },
          {
            "topic": "Failure semantics",
            "choice": "Fail closed for inaccessible labels; safe generic handling for unexpected failures",
            "rationale": "The board must not reveal label existence or details to an unauthorized actor, while operational errors remain observable without leaking internals."
          },
